sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_cmode;
uniform float amzp_mixAmt;
uniform float amzp_lineW;
uniform float amzp_edge;
uniform float amzp_edgeTh;
uniform float amzp_hatch;
uniform float amzp_hSpace;
uniform float amzp_hAngle;
uniform float amzp_crossOn;
uniform float amzp_tone;
uniform float amzp_wobble;
layout(color) uniform half4 amzp_pencil;
layout(color) uniform half4 amzp_paper;
uniform float amzp_grainAmt;
uniform float amzp_smudge;
uniform float amzp_colAmt;
uniform float amzp_keepAlpha;
uniform float amzp_boil;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hh(i), hh(i + float2(1.0, 0.0)), f.x), mix(hh(i + float2(0.0, 1.0)), hh(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float4 at(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float lum(float4 c) { return c.a > 0.0001 ? dot(c.rgb / c.a, float3(0.299, 0.587, 0.114)) * c.a + (1.0 - c.a) : 1.0; }
    float hatchL(float2 p, float ang, float dark, float bt) {
        float a = radians(ang);
        float2 d = float2(cos(a), sin(a));
        float2 n = float2(-d.y, d.x);
        float sp = max(amzp_hSpace, 1.5);
        float along = dot(p, d), across = dot(p, n);
        across += (vn(float2(along / (sp * 6.0), across / sp * 0.3) + bt) - 0.5) * amzp_wobble * sp * 0.8;
        float k = across / sp;
        float lid = floor(k);
        float f = abs(fract(k) - 0.5) * 2.0;
        float w = clamp(dark, 0.0, 1.0) * 0.9;
        float brk = vn(float2(along / (sp * 3.0) + lid * 7.1, lid) + bt * 3.0);
        w *= smoothstep(0.15, 0.45, brk + dark * 0.4);
        return 1.0 - smoothstep(w - 0.25, w + 0.05, f);
    }
    void nmFxMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float2 p = uv * W;
        float4 src = at(uv);
        float bt = amzp_boil > 0.0 ? floor(time * amzp_boil) * 1.37 : 0.0;
        float2 jit = amzp_boil > 0.0 ? (float2(hh(float2(bt, 1.0)), hh(float2(bt, 2.0))) - 0.5) * 0.8 : float2(0.0);
        float2 e = max(amzp_lineW, 0.5) / W;
        float2 ue = uv + jit / W;
        float tl = lum(at(ue + float2(-e.x, e.y))), tc = lum(at(ue + float2(0.0, e.y))), tr = lum(at(ue + float2(e.x, e.y)));
        float ml = lum(at(ue + float2(-e.x, 0.0))), mr = lum(at(ue + float2(e.x, 0.0)));
        float bl = lum(at(ue + float2(-e.x, -e.y))), bc = lum(at(ue + float2(0.0, -e.y))), br = lum(at(ue + float2(e.x, -e.y)));
        float gx = (tr + 2.0 * mr + br) - (tl + 2.0 * ml + bl);
        float gy = (tl + 2.0 * tc + tr) - (bl + 2.0 * bc + br);
        float g = length(float2(gx, gy));
        float ol = clamp((g - amzp_edgeTh) * amzp_edge * 2.5, 0.0, 1.0);
        ol *= 0.75 + 0.25 * vn(p / 3.0 + bt);
        float L = lum(src);
        float dark = clamp((1.0 - L) * amzp_tone, 0.0, 1.0);
        float charcoal = int(amzp_cmode) == 2 ? 1.0 : 0.0;
        float h1 = hatchL(p, amzp_hAngle, dark * amzp_hatch * (1.0 + charcoal * 0.4), bt);
        float h2 = (amzp_crossOn>0.5) ? hatchL(p, amzp_hAngle + 90.0, (dark - 0.45) * 1.8 * amzp_hatch, bt + 5.0) : 0.0;
        float hat = max(h1, h2);
        float grain = vn(p / 1.3) * 0.6 + vn(p / 4.0 + 9.0) * 0.4;
        float sm = dark * amzp_smudge * (0.6 + 0.4 * vn(p / 18.0 + bt));
        float ink = max(ol, hat * (0.65 + 0.35 * grain));
        ink = max(ink, sm * 0.55);
        ink *= 1.0 - amzp_grainAmt * 0.6 * (1.0 - grain) * (1.0 - charcoal * 0.3);
        if (int(amzp_cmode) == 2) ink = clamp(ink * 1.25 + dark * 0.15, 0.0, 1.0);
        ink = clamp(ink, 0.0, 1.0);
        float3 pc = amzp_pencil.rgb;
        if (int(amzp_cmode) == 1) {
            float3 sc = src.a > 0.0001 ? src.rgb / src.a : float3(1.0);
            float sl = dot(sc, float3(0.299, 0.587, 0.114));
            float3 colp = clamp(mix(float3(sl), sc, 1.0 + amzp_colAmt * 0.6) * 0.75, 0.0, 1.0);
            pc = mix(amzp_pencil.rgb, colp, clamp(amzp_colAmt, 0.0, 1.0));
        }
        if (int(amzp_cmode) == 2) pc *= 0.7;
        float3 pap = amzp_paper.rgb * (1.0 - amzp_grainAmt * 0.12 * (1.0 - grain));
        float4 res;
        if ((amzp_keepAlpha>0.5)) {
            res = float4(pc, 1.0) * ink * src.a;
        } else {
            res = float4(mix(pap, pc, ink), 1.0) * src.a;
        }
        amzOutput = mix(src, res, clamp(amzp_mixAmt, 0.0, 1.0));
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
